result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "dotenv.py", "content": """"Minimal .env parser (Python stdlib only)."""

import re

__all__ = ["DotEnvError", "parse"]

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")
_INTERP_RE = re.compile(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}")
_ESCAPES = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}


class DotEnvError(ValueError):
    """Raised on malformed .env input."""

    def __init__(self, lineno, message):
        super().__init__("line %d: %s" % (lineno, message))
        self.lineno = lineno


def _interpolate(value, variables):
    return _INTERP_RE.sub(lambda m: variables.get(m.group(1), ""), value)


def _parse_double_quoted(rest, lineno):
    """Parse a double-quoted value starting at rest[0] == '"'."""
    out = []
    i = 1
    while i < len(rest):
        ch = rest[i]
        if ch == "\\":
            if i + 1 >= len(rest):
                # Escape sequence truncated by a raw newline.
                raise DotEnvError(lineno, "raw newline inside double-quoted value")
            nxt = rest[i + 1]
            if nxt == "\n":
                raise DotEnvError(lineno, "raw newline inside double-quoted value")
            out.append(_ESCAPES.get(nxt, "\\" + nxt))
            i += 2
        elif ch == "\n":
            raise DotEnvError(
                lineno,
                "raw newline inside double-quoted value "
                "(use \\n escape for multi-line values)",
            )
        elif ch == '"':
            return "".join(out)
        else:
            out.append(ch)
            i += 1
    raise DotEnvError(lineno, "unterminated double-quoted value")


def _parse_single_quoted(rest, lineno):
    """Parse a single-quoted value starting at rest[0] == "'"; fully literal."""
    end = rest.find("'", 1)
    if end == -1:
        raise DotEnvError(lineno, "unterminated single-quoted value")
    return rest[1:end]


def parse(text):
    """Parse .env-formatted *text* into a dict.

    Rules:
      - ``KEY=VALUE`` per line; optional ``export `` prefix; blank lines and
        ``#`` comment lines ignored.
      - Keys match ``[A-Za-z_][A-Za-z0-9_]*``.
      - Unquoted values are trimmed and end at a ``#`` comment.
      - Single-quoted values are literal.
      - Double-quoted values honor ``\\n \\t \\" \\\\`` escapes; raw newlines
        inside them are errors (use ``\\n`` instead).
      - ``${VAR}`` interpolation in double-quoted and unquoted values resolves
        against previously parsed keys (undefined -> empty string).
    """
    variables = {}
    for lineno, raw_line in enumerate(text.splitlines(), 1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        if line.startswith("export ") or line.startswith("export\t"):
            line = line[len("export"):].lstrip()

        key, sep, rest = line.partition("=")
        if not sep:
            raise DotEnvError(lineno, "expected KEY=VALUE")
        key = key.strip()
        if not _KEY_RE.match(key):
            raise DotEnvError(lineno, "invalid key %r" % key)

        rest = rest.lstrip()
        if rest.startswith('"'):
            value = _parse_double_quoted(rest, lineno)
            variables[key] = _interpolate(value, variables)
        elif rest.startswith("'"):
            variables[key] = _parse_single_quoted(rest, lineno)
        else:
            hash_pos = rest.find("#")
            if hash_pos != -1:
                rest = rest[:hash_pos]
            variables[key] = _interpolate(rest.strip(), variables)

    return variables
